import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.D8Tso2Ul.js";const m=JSON.parse('{"title":"Rol: Supervisor","description":"","frontmatter":{},"headers":[],"relativePath":"roles/supervisor.md","filePath":"roles/supervisor.md"}'),i={name:"roles/supervisor.md"};function d(s,a,l,c,n,u){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="rol-supervisor" tabindex="-1">Rol: Supervisor <a class="header-anchor" href="#rol-supervisor" aria-label="Permalink to &quot;Rol: Supervisor&quot;">​</a></h1><p>El <strong>supervisor</strong> lidera a un equipo de trabajadores en terreno. Es un rol operativo clave en la captura de firmas y el registro de actividades.</p><h2 id="responsabilidades" tabindex="-1">Responsabilidades <a class="header-anchor" href="#responsabilidades" aria-label="Permalink to &quot;Responsabilidades&quot;">​</a></h2><ul><li>Supervisar a los trabajadores de su equipo en la obra.</li><li>Dictar y firmar charlas y capacitaciones como <strong>relator</strong>.</li><li>Verificar y firmar la entrega de EPP.</li><li>Reportar incidentes y condiciones subestándar.</li></ul><h2 id="permisos" tabindex="-1">Permisos <a class="header-anchor" href="#permisos" aria-label="Permalink to &quot;Permisos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Módulo</th><th>Acceso</th></tr></thead><tbody><tr><td>Dashboard</td><td>✓ Estado de su equipo y firmas pendientes</td></tr><tr><td>Obras</td><td>👁 Solo lectura</td></tr><tr><td>Documentos</td><td>👁 Solo lectura</td></tr><tr><td>Firmas</td><td>✓ Firma propia y como relator</td></tr><tr><td>Incidentes</td><td>✓ Reportar y dar seguimiento</td></tr><tr><td>Actividades</td><td>✓ Dictar y firmar como relator</td></tr><tr><td>Encuestas</td><td>👁 Solo lectura</td></tr><tr><td>Asistente IA</td><td>✗ Sin acceso</td></tr><tr><td>Personas</td><td>👁 Solo lectura (su equipo)</td></tr><tr><td>Bandeja de Entrada</td><td>✓ Completo</td></tr><tr><td>Tenants</td><td>✗ Sin acceso</td></tr></tbody></table><h2 id="firma-como-relator" tabindex="-1">Firma como relator <a class="header-anchor" href="#firma-como-relator" aria-label="Permalink to &quot;Firma como relator&quot;">​</a></h2><p>El supervisor es uno de los roles que puede actuar como <strong>relator</strong> en actividades (<code>CAPACITACION_SST</code>, <code>CHARLA_5MIN</code>). Su firma cruzada (<code>tipoFirma: relator</code>) certifica que la actividad se impartió, complementando las firmas de asistencia de los trabajadores. Ver <a href="/manual/ds44/capacitaciones.html">Capacitaciones</a> y <a href="/manual/modulos/firmas.html">Firmas</a>.</p><h2 id="verificacion-de-epp" tabindex="-1">Verificación de EPP <a class="header-anchor" href="#verificacion-de-epp" aria-label="Permalink to &quot;Verificación de EPP&quot;">​</a></h2><p>Firma como <code>supervisor</code> la entrega de EPP, validando que el trabajador recibió el equipo adecuado a su cargo. Ver <a href="/manual/ds44/epp.html">Entrega de EPP</a>.</p>',10)])])}const h=e(i,[["render",d]]);export{m as __pageData,h as default};
